import { type FormEvent, type ReactNode, useCallback, useEffect, useState } from "react";
import { Link, Navigate, Route, Routes, useLocation, useNavigate } from "react-router-dom";
import { io } from "socket.io-client";
import { QRCodeSVG } from "qrcode.react";
import { ArrowRight, BellRing, Check, ChevronRight, ClipboardCheck, Clock3, LogOut, MapPin, Plus, QrCode, RefreshCw, Search, ShieldCheck, Users, X } from "lucide-react";
import { loginPathForCheckIn, readCheckInProof, safePostLoginPath } from "@queueless/shared";
import { api, patch, post, remove } from "./client";
import { copyTextFromUserGesture } from "./clipboard";

type Role = "STUDENT" | "STAFF" | "ADMIN";
type User = { id: string; name: string; email: string; role: Role };
type Service = { id: string; name: string; code: string; description: string; averageMinutes: number; active?: boolean; location: { name: string; building: string; floor: string }; queue?: { id: string; status: string } | null; checkinLeadMinutes?: number; checkinLeadTokens?: number; checkinGraceMinutes?: number };
type Token = { id: string; displayToken: string; status: string; position: number | null; estimatedWaitMinutes: number | null; joinedAt: string; checkinOpenedAt?: string | null; checkinDeadlineAt?: string | null; reason?: string | null; queueId: string; service: Service; user?: { id: string; name: string } };
type CounterQr = { url: string; proof: string; expiresAt: string; serverTime: string; rotationSeconds: number; allowDemoProof: boolean };
const labels: Record<string, string> = { WAITING: "Waiting", CHECKIN_REQUIRED: "Check-in required", CHECKED_IN: "Checked in", CALLED: "Called", SERVING: "In service", COMPLETED: "Completed", NO_SHOW: "No show", CANCELLED: "Cancelled", SKIPPED: "Skipped", OPEN: "Open", CLOSED: "Closed", PAUSED: "Paused" };
const statusClass = (status: string) => status === "CHECKED_IN" || status === "COMPLETED" ? "bg-green/10 text-green" : status === "CHECKIN_REQUIRED" || status === "CALLED" ? "bg-amber/10 text-amber" : status === "NO_SHOW" || status === "CANCELLED" || status === "SKIPPED" ? "bg-red/10 text-red" : "bg-slate-100 text-slate-600";
const nice = (status: string) => labels[status] ?? status.replaceAll("_", " ");
const time = (value?: string | null) => value ? new Intl.DateTimeFormat(undefined, { hour: "numeric", minute: "2-digit" }).format(new Date(value)) : "—";
const date = (value?: string | null) => value ? new Intl.DateTimeFormat(undefined, { month: "short", day: "numeric", hour: "numeric", minute: "2-digit" }).format(new Date(value)) : "—";

function useQueueEvents(queueIds: string[], refresh: () => void) {
  useEffect(() => {
    const socket = io({ path: "/socket.io", transports: ["websocket", "polling"] });
    socket.on("connect", () => queueIds.forEach((queueId) => socket.emit("queue:subscribe", { queueId })));
    socket.on("queue:updated", refresh); socket.on("token:updated", refresh);
    const visibility = () => { if (!document.hidden) refresh(); };
    window.addEventListener("focus", refresh); document.addEventListener("visibilitychange", visibility);
    return () => { socket.disconnect(); window.removeEventListener("focus", refresh); document.removeEventListener("visibilitychange", visibility); };
  }, [queueIds.join(","), refresh]);
}
function useSessionEvents(refresh: () => void) {
  useEffect(() => {
    const socket = io({ path: "/socket.io", transports: ["websocket", "polling"] });
    socket.on("sessions:updated", refresh);
    return () => { socket.disconnect(); };
  }, [refresh]);
}

function Brand() { return <Link to="/" className="flex items-center gap-2.5 text-ink no-underline"><span className="grid h-8 w-8 place-items-center rounded-[9px] bg-teal text-sm font-black text-white"><span className="relative -top-px">Q</span></span><span className="text-[17px] font-bold tracking-[-.035em]">QueueLess</span></Link>; }
function Status({ value }: { value: string }) { return <span className={`status ${statusClass(value)}`}><span className="h-1.5 w-1.5 rounded-full bg-current"/>{nice(value)}</span>; }
function Empty({ title, detail, action }: { title: string; detail: string; action?: ReactNode }) { return <div className="card px-6 py-12 text-center"><p className="text-base font-bold text-ink">{title}</p><p className="mx-auto mt-2 max-w-md text-sm leading-6 text-muted">{detail}</p>{action && <div className="mt-5">{action}</div>}</div>; }
function Notice({ children, tone = "teal" }: { children: ReactNode; tone?: "teal" | "red" | "amber" }) { const style = tone === "red" ? "border-red/20 bg-red/5 text-red" : tone === "amber" ? "border-amber/20 bg-amber/5 text-amber" : "border-teal/15 bg-teal/5 text-teal-deep"; return <div className={`rounded-lg border px-3.5 py-3 text-sm leading-5 ${style}`}>{children}</div>; }
function Countdown({ until, serverTime, expiredLabel = "Expired" }: { until?: string | null; serverTime?: string | null; expiredLabel?: string }) {
  const [clock, setClock] = useState(() => ({ now: Date.now(), offset: serverTime ? Date.parse(serverTime) - Date.now() : 0 }));
  useEffect(() => { setClock({ now: Date.now(), offset: serverTime ? Date.parse(serverTime) - Date.now() : 0 }); }, [serverTime]);
  useEffect(() => { const handle = window.setInterval(() => setClock((current) => ({ ...current, now: Date.now() })), 1_000); return () => window.clearInterval(handle); }, []);
  if (!until) return null;
  const seconds = Math.max(0, Math.ceil((Date.parse(until) - (clock.now + clock.offset)) / 1_000));
  if (!seconds) return <span>{expiredLabel}</span>;
  const minutes = Math.floor(seconds / 60); const remainder = seconds % 60;
  return <span>{minutes ? `${minutes}m ${String(remainder).padStart(2, "0")}s` : `${remainder}s`}</span>;
}

function CheckInGate({ user }: { user: User | null }) {
  const location = useLocation();
  return user ? <CheckInPage/> : <Navigate to={loginPathForCheckIn(location.pathname, location.search)} replace />;
}

export function App() {
  const [user, setUser] = useState<User | null | undefined>(undefined);
  const refreshUser = useCallback(async () => { try { const result = await api<{ user: User }>("/api/auth/me"); setUser(result.user); } catch { setUser(null); } }, []);
  useEffect(() => { void refreshUser(); }, [refreshUser]);
  if (user === undefined) return <div className="grid min-h-screen place-items-center"><div className="h-7 w-7 animate-pulse rounded-lg bg-teal/20" aria-label="Loading"/></div>;
  return <Routes>
    <Route path="/" element={user ? <Navigate to={user.role === "STUDENT" ? "/student" : user.role === "STAFF" ? "/staff" : "/admin"} replace /> : <Landing />} />
    <Route path="/login" element={<Auth user={user} onAuthenticated={refreshUser}/>} />
    <Route path="/check-in/confirm" element={<CheckInGate user={user} />} />
    <Route path="/student" element={user?.role === "STUDENT" ? <StudentPortal user={user} onLogout={() => logout(setUser)}/> : <Navigate to="/login" replace />} />
    <Route path="/staff" element={user && ["STAFF", "ADMIN"].includes(user.role) ? <StaffPortal user={user} onLogout={() => logout(setUser)}/> : <Navigate to="/login" replace />} />
    <Route path="/admin" element={user?.role === "ADMIN" ? <AdminPortalV2 user={user} onLogout={() => logout(setUser)}/> : <Navigate to="/login" replace />} />
    <Route path="*" element={<Navigate to="/" replace/>}/>
  </Routes>;
}
async function logout(setUser: (user: null) => void) { await post<void>("/api/auth/logout"); setUser(null); }

function Landing() { return <div className="min-h-screen bg-canvas"><header className="shell flex h-18 items-center justify-between"><Brand/><Link className="btn btn-primary no-underline" to="/login">Sign in <ArrowRight size={16}/></Link></header><main className="shell grid gap-12 pb-16 pt-16 lg:grid-cols-[1.02fr_.98fr] lg:pt-24"><section className="max-w-xl"><p className="eyebrow text-teal">Campus service queues, considered</p><h1 className="mt-4 text-4xl font-semibold leading-[1.08] tracking-[-.055em] text-ink sm:text-5xl">Know when to arrive. Keep the counter moving.</h1><p className="mt-6 max-w-lg text-base leading-7 text-muted">QueueLess lets students join from anywhere, then confirms presence at the counter before their turn. Less waiting, clearer service.</p><div className="mt-8 flex flex-wrap gap-3"><Link className="btn btn-primary no-underline" to="/login">Open QueueLess <ArrowRight size={16}/></Link><a className="btn btn-secondary" href="#how">How it works</a></div><div className="mt-12 grid grid-cols-3 gap-5 border-t border-line pt-6"><Metric value="Live" label="queue updates"/><Metric value="QR" label="presence check"/><Metric value="35 s" label="demo no-show"/></div></section><QueueSchematic/></main><section id="how" className="border-y border-line bg-white"><div className="shell grid gap-px py-4 md:grid-cols-3"><Feature icon={<Clock3/>} title="Join with context" detail="See availability, location and an estimated wait before taking a token."/><Feature icon={<QrCode/>} title="Check in at the counter" detail="A rotating, time-limited QR keeps the queue moving for those present."/><Feature icon={<ShieldCheck/>} title="Operate with confidence" detail="Role-based staff controls and an auditable record for every decision."/></div></section></div>; }
function Metric({ value, label }: { value: string; label: string }) { return <div><p className="text-lg font-bold tracking-[-.03em]">{value}</p><p className="mt-0.5 text-xs leading-4 text-muted">{label}</p></div>; }
function Feature({ icon, title, detail }: { icon: ReactNode; title: string; detail: string }) { return <div className="px-5 py-8 md:border-r md:last:border-r-0 md:border-line"><span className="text-teal">{icon}</span><h2 className="mt-4 text-sm font-bold">{title}</h2><p className="mt-2 text-sm leading-6 text-muted">{detail}</p></div>; }
function QueueSchematic() { return <div className="card relative overflow-hidden p-5 sm:p-7"><div className="absolute inset-x-0 top-0 h-1 bg-teal"/><div className="flex items-center justify-between border-b border-line pb-5"><div><p className="eyebrow">Student Services Centre</p><p className="mt-1 text-sm font-bold">Bonafide Certificate</p></div><Status value="OPEN"/></div><div className="space-y-3 py-6"><div className="flex items-center justify-between rounded-lg border border-teal/20 bg-teal/5 p-4"><div><p className="text-xs font-bold tracking-[.1em] text-teal">YOUR TOKEN</p><p className="mt-1 text-3xl font-semibold tracking-[-.05em]">BON-014</p></div><div className="text-right"><p className="text-sm font-bold">2 ahead</p><p className="mt-1 text-xs text-muted">~10 min estimate</p></div></div>{["BON-012  ·  At counter", "BON-013  ·  Checked in", "BON-014  ·  Your token"].map((row, index) => <div className="flex items-center gap-3 text-sm" key={row}><span className={`grid h-6 w-6 place-items-center rounded-full text-xs font-bold ${index === 2 ? "bg-teal text-white" : "bg-slate-100 text-muted"}`}>{index + 1}</span><span className={index === 2 ? "font-bold" : "text-muted"}>{row}</span></div>)}</div><div className="rounded-lg border border-line bg-canvas px-4 py-3 text-sm text-muted">A check-in window opens as your turn approaches.</div></div>; }

function Auth({ user, onAuthenticated }: { user: User | null; onAuthenticated: () => Promise<void> }) {
  const [mode, setMode] = useState<"login" | "register">("login"); const [demo, setDemo] = useState(false); const [error, setError] = useState(""); const [busy, setBusy] = useState(false); const navigate = useNavigate(); const location = useLocation(); const next = safePostLoginPath(location.search);
  useEffect(() => { void api<{ demoMode: boolean }>("/api/public/config").then((r) => setDemo(r.demoMode)); }, []);
  if (user) return <Navigate to={next} replace />;
  async function submit(event: FormEvent<HTMLFormElement>) { event.preventDefault(); setError(""); setBusy(true); const data = new FormData(event.currentTarget); try { await post(mode === "login" ? "/api/auth/login" : "/api/auth/register", mode === "login" ? { email: data.get("email"), password: data.get("password") } : { name: data.get("name"), email: data.get("email"), password: data.get("password") }); await onAuthenticated(); navigate(next, { replace: true }); } catch (e) { setError(e instanceof Error ? e.message : "Unable to continue."); } finally { setBusy(false); } }
  async function demoLogin(email: string) { setBusy(true); setError(""); try { await post("/api/auth/login", { email, password: "Demo@12345" }); await onAuthenticated(); navigate(next, { replace: true }); } catch (e) { setError(e instanceof Error ? e.message : "Demo login failed."); } finally { setBusy(false); } }
  return <div className="min-h-screen bg-canvas"><header className="shell flex h-18 items-center"><Brand/></header><main className="mx-auto max-w-md px-4 py-10 sm:py-16"><div className="card p-6 sm:p-8"><p className="eyebrow text-teal">QueueLess account</p><h1 className="mt-2 text-2xl font-semibold tracking-[-.04em]">{mode === "login" ? "Welcome back" : "Create a student account"}</h1><p className="mt-2 text-sm leading-6 text-muted">{mode === "login" ? "Sign in to see your queue and next steps." : "Registration always creates a student account."}</p>{error && <div className="mt-5"><Notice tone="red">{error}</Notice></div>}<form className="mt-6 space-y-4" onSubmit={submit}>{mode === "register" && <label className="block text-sm font-semibold">Full name<input required name="name" className="field" autoComplete="name"/></label>}<label className="block text-sm font-semibold">College email<input required name="email" type="email" className="field" autoComplete="email" placeholder="you@example.edu"/></label><label className="block text-sm font-semibold">Password<input required name="password" type="password" minLength={8} className="field" autoComplete={mode === "login" ? "current-password" : "new-password"}/></label><button disabled={busy} className="btn btn-primary mt-2 w-full" type="submit">{busy ? "Please wait…" : mode === "login" ? "Sign in" : "Create account"}</button></form><p className="mt-5 text-center text-sm text-muted">{mode === "login" ? "New here?" : "Already registered?"} <button className="font-bold text-teal hover:underline" onClick={() => { setMode(mode === "login" ? "register" : "login"); setError(""); }}>{mode === "login" ? "Create an account" : "Sign in"}</button></p>{demo && <div className="mt-7 border-t border-line pt-5"><p className="eyebrow">Demo accounts · local only</p><div className="mt-3 grid gap-2"><DemoButton label="Student · Anaya" onClick={() => demoLogin("anaya@queueless.local")}/><DemoButton label="Staff · Mira" onClick={() => demoLogin("staff@queueless.local")}/><DemoButton label="Administrator" onClick={() => demoLogin("admin@queueless.local")}/></div></div>}</div></main></div>;
}
function DemoButton({ label, onClick }: { label: string; onClick: () => void }) { return <button onClick={onClick} className="flex items-center justify-between rounded-lg border border-line px-3 py-2.5 text-left text-sm font-semibold transition-colors hover:bg-canvas"><span>{label}</span><ChevronRight size={15} className="text-muted"/></button>; }

function PortalHeader({ user, onLogout, title, description, role }: { user: User; onLogout: () => Promise<void>; title: string; description: string; role: string }) { const navigate = useNavigate(); async function signOut() { await onLogout(); navigate("/login", { replace: true }); } return <><header className="border-b border-line bg-white"><div className="shell flex min-h-18 items-center justify-between gap-4"><Brand/><div className="flex items-center gap-3"><div className="hidden text-right sm:block"><p className="text-sm font-bold">{user.name}</p><p className="text-xs text-muted">{role}</p></div><button onClick={() => void signOut()} className="btn btn-secondary min-h-9 px-3" aria-label="Sign out"><LogOut size={16}/><span className="hidden sm:inline">Sign out</span></button></div></div></header><div className="border-b border-line bg-canvas"><div className="shell py-6"><p className="eyebrow text-teal">{role}</p><h1 className="mt-1 text-2xl font-semibold tracking-[-.04em]">{title}</h1><p className="mt-1 text-sm text-muted">{description}</p></div></div></>; }

function StudentPortal({ user, onLogout }: { user: User; onLogout: () => Promise<void> }) {
  const [services, setServices] = useState<Service[]>([]); const [tokens, setTokens] = useState<Token[]>([]); const [serverTime, setServerTime] = useState<string | null>(null); const [search, setSearch] = useState(""); const [notice, setNotice] = useState(""); const [error, setError] = useState(""); const [loading, setLoading] = useState(true);
  const refresh = useCallback(async () => { try { const [a, b] = await Promise.all([api<{ services: Service[] }>("/api/services"), api<{ tokens: Token[]; serverTime: string }>("/api/tokens/me")]); setServices(a.services); setTokens(b.tokens); setServerTime(b.serverTime); setError(""); } catch (e) { setError(e instanceof Error ? e.message : "Could not load your portal."); } finally { setLoading(false); } }, []);
  useEffect(() => { void refresh(); }, [refresh]); useQueueEvents(tokens.map((t) => t.queueId), refresh);
  const active = tokens.find((t) => ["WAITING", "CHECKIN_REQUIRED", "CHECKED_IN", "CALLED", "SERVING"].includes(t.status)); const filtered = services.filter((s) => `${s.name} ${s.description} ${s.location.name}`.toLowerCase().includes(search.toLowerCase()));
  async function join(queueId?: string) { if (!queueId) return; setNotice(""); try { const result = await post<{ token: Token }>(`/api/queues/${queueId}/tokens`); setNotice(`${result.token.displayToken} has been added to your queue.`); await refresh(); } catch (e) { setError(e instanceof Error ? e.message : "Unable to join this queue."); } }
  async function cancel(token: Token) { if (!confirm(`Cancel ${token.displayToken}?`)) return; try { await post(`/api/tokens/${token.id}/cancel`); await refresh(); } catch (e) { setError(e instanceof Error ? e.message : "Could not cancel token."); } }
  return <div className="min-h-screen bg-canvas"><PortalHeader user={user} onLogout={onLogout} role="Student portal" title="Your campus queues" description="Join a service remotely, then check in at the counter when prompted."/><main className="shell py-7 sm:py-9">{error && <div className="mb-5"><Notice tone="red">{error}</Notice></div>}{notice && <div className="mb-5"><Notice>{notice}</Notice></div>}{loading ? <div className="grid gap-5 lg:grid-cols-[1.25fr_.75fr]"><Skeleton/><Skeleton/></div> : <div className="grid gap-7 lg:grid-cols-[1.25fr_.75fr]"><section>{active ? <TokenReceipt token={active} serverTime={serverTime} onCancel={() => cancel(active)}/> : <Empty title="No active token" detail="Choose an open campus service below when you need help."/>}<div className="mt-8"><div className="flex flex-col justify-between gap-3 sm:flex-row sm:items-end"><div><p className="eyebrow">Service directory</p><h2 className="mt-1 text-xl font-semibold tracking-[-.035em]">Find a counter</h2></div><label className="relative"><Search className="pointer-events-none absolute left-3 top-2.5 text-muted" size={17}/><input className="field mt-0 w-full pl-9 sm:w-64" value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Search services"/></label></div><div className="mt-4 grid gap-3 sm:grid-cols-2">{filtered.map((service) => <ServiceCard key={service.id} service={service} disabled={Boolean(active)} onJoin={() => join(service.queue?.id)}/>)}</div></div></section><aside><div className="card p-5"><p className="eyebrow">How it works</p><ol className="mt-4 space-y-4">{[["1", "Join", "Take a token from an open service."], ["2", "Wait remotely", "Follow the live position and estimate."], ["3", "Check in", "Scan the rotating QR at the counter."], ["4", "Be served", "Staff call verified students first."]].map(([n, h, d]) => <li className="flex gap-3" key={n}><span className="grid h-6 w-6 shrink-0 place-items-center rounded-full bg-teal/10 text-xs font-bold text-teal">{n}</span><div><p className="text-sm font-bold">{h}</p><p className="mt-0.5 text-xs leading-5 text-muted">{d}</p></div></li>)}</ol></div><div className="mt-4 rounded-[10px] border border-amber/20 bg-amber/5 p-5"><BellRing size={19} className="text-amber"/><p className="mt-3 text-sm font-bold text-amber">Be ready near your turn</p><p className="mt-1 text-sm leading-6 text-amber/85">An unverified token can be bypassed until its check-in deadline. Times are estimates.</p></div>{tokens.filter((t) => !["WAITING", "CHECKIN_REQUIRED", "CHECKED_IN", "CALLED", "SERVING"].includes(t.status)).length > 0 && <div className="card mt-4 p-5"><p className="eyebrow">Recent history</p><div className="mt-3 divide-y divide-line">{tokens.filter((t) => !["WAITING", "CHECKIN_REQUIRED", "CHECKED_IN", "CALLED", "SERVING"].includes(t.status)).slice(0, 4).map((t) => <div className="flex items-center justify-between py-3" key={t.id}><div><p className="text-sm font-bold">{t.displayToken}</p><p className="text-xs text-muted">{t.service.name}</p></div><Status value={t.status}/></div>)}</div></div>}</aside></div>}</main></div>;
}
function Skeleton() { return <div className="card h-72 animate-pulse bg-white"/>; }
function TokenReceipt({ token, serverTime, onCancel }: { token: Token; serverTime: string | null; onCancel: () => void }) { const checkin = token.status === "CHECKIN_REQUIRED"; return <div className="card overflow-hidden"><div className="flex items-start justify-between border-b border-line px-5 py-4 sm:px-6"><div><p className="eyebrow text-teal">Active token</p><p className="mt-1 text-sm font-bold">{token.service.name}</p></div><Status value={token.status}/></div><div className="grid gap-6 p-5 sm:grid-cols-[1fr_auto] sm:p-6"><div><p className="text-5xl font-semibold tracking-[-.07em] text-ink sm:text-6xl">{token.displayToken}</p><div className="mt-5 grid grid-cols-2 gap-4 border-y border-line py-4 sm:max-w-md"><div><p className="eyebrow">Ahead of you</p><p className="mt-1 text-xl font-bold">{token.position ?? "—"}</p></div><div><p className="eyebrow">Estimated wait</p><p className="mt-1 text-xl font-bold">{token.estimatedWaitMinutes === null ? "—" : token.estimatedWaitMinutes === 0 ? "Ready soon" : `~${token.estimatedWaitMinutes} min`}</p></div></div><p className="mt-4 flex items-center gap-2 text-sm text-muted"><MapPin size={16}/>{token.service.location.name}, {token.service.location.building} · {token.service.location.floor}</p>{checkin && <div className="mt-5"><Link className="btn btn-primary no-underline" to={`/check-in/confirm?token=${token.id}`}>Check in at counter <QrCode size={16}/></Link><p className="mt-2 text-xs text-muted">Scan the counter QR with your phone. Deadline: {time(token.checkinDeadlineAt)} · <span className="font-bold text-amber">Time remaining: <Countdown until={token.checkinDeadlineAt} serverTime={serverTime} expiredLabel="Deadline expired"/></span></p></div>}</div><div className="rounded-lg bg-canvas p-4 sm:w-48"><p className="eyebrow">What happens next</p><p className="mt-2 text-sm font-semibold leading-6">{checkin ? "Please verify your presence at the service counter." : token.status === "CHECKED_IN" ? "You’re verified. Staff can call you next." : token.status === "CALLED" ? "Please approach the counter now." : token.status === "SERVING" ? "Your service is in progress." : "We’ll open a check-in window as your turn gets closer."}</p></div></div>{["WAITING", "CHECKIN_REQUIRED"].includes(token.status) && <div className="border-t border-line px-5 py-3 text-right sm:px-6"><button className="text-sm font-semibold text-red hover:underline" onClick={onCancel}>Cancel token</button></div>}</div>; }
function ServiceCard({ service, disabled, onJoin }: { service: Service; disabled: boolean; onJoin: () => void }) { const closed = service.queue?.status !== "OPEN"; return <div className="card flex flex-col p-4"><div className="flex items-start justify-between gap-3"><div><p className="text-sm font-bold">{service.name}</p><p className="mt-1 text-xs leading-5 text-muted">{service.description}</p></div><Status value={service.queue?.status ?? "CLOSED"}/></div><div className="mt-4 flex items-center justify-between border-t border-line pt-3"><span className="text-xs text-muted">~{service.averageMinutes} min/service</span><button disabled={disabled || closed} onClick={onJoin} className="btn btn-secondary min-h-8 px-3 text-xs">{disabled ? "Active token exists" : closed ? "Closed" : "Join queue"}</button></div></div>; }

function CheckInPage() { const location = useLocation(); const navigate = useNavigate(); const proof = readCheckInProof(location.search); const [status, setStatus] = useState<"ready" | "working" | "success" | "error">("ready"); const [message, setMessage] = useState(""); const [demoProof, setDemoProof] = useState(""); const [demoMode, setDemoMode] = useState(false);
  useEffect(() => { void api<{ demoMode: boolean }>("/api/public/config").then((config) => setDemoMode(config.demoMode)); }, []);
  async function confirm(value = proof ?? demoProof) { if (!value) { setMessage("Open this page from a current counter QR code."); setStatus("error"); return; } setStatus("working"); try { const result = await post<{ message: string }>("/api/check-ins/verify", { proof: value }); setMessage(result.message); setStatus("success"); } catch (e) { setMessage(e instanceof Error ? e.message : "Unable to verify this QR code."); setStatus("error"); } }
  return <div className="min-h-screen bg-canvas"><header className="shell flex h-18 items-center"><Brand/></header><main className="mx-auto max-w-lg px-4 py-12"><div className="card p-6 sm:p-8"><QrCode className="text-teal" size={28}/><p className="eyebrow mt-5">Counter presence check</p><h1 className="mt-2 text-2xl font-semibold tracking-[-.04em]">Confirm you’re here</h1><p className="mt-2 text-sm leading-6 text-muted">Signed codes expire quickly and confirm eligibility for the service currently shown at the counter.</p>{status === "success" ? <div className="mt-6"><Notice>{message}</Notice><button className="btn btn-primary mt-5" onClick={() => navigate("/student")}>Return to my queue</button></div> : <><button disabled={status === "working"} className="btn btn-primary mt-6 w-full" onClick={() => confirm()}>{status === "working" ? "Verifying…" : proof ? "Confirm check-in" : "Verify counter QR"}</button>{status === "error" && <div className="mt-4"><Notice tone="red">{message}</Notice></div>}{!proof && demoMode && <details className="mt-6 rounded-lg border border-line p-4"><summary className="cursor-pointer text-sm font-bold">Demo-only proof entry</summary><p className="mt-2 text-xs leading-5 text-muted">For a one-laptop presentation, staff can copy the currently displayed signed counter proof here. It uses the same server verification path.</p><textarea aria-label="Demo QR proof" value={demoProof} onChange={(e) => setDemoProof(e.target.value)} className="field h-20 resize-none"/><button className="btn btn-secondary mt-2" onClick={() => confirm(demoProof)}>Verify demo proof</button></details>}</>}</div></main></div>; }

function StaffPortal({ user, onLogout }: { user: User; onLogout: () => Promise<void> }) {
  const [services, setServices] = useState<Service[]>([]); const [selected, setSelected] = useState(""); const [queue, setQueue] = useState<{ id: string; status: string; service: Service; tokens: Token[] } | null>(null); const [qr, setQr] = useState<CounterQr | null>(null); const [error, setError] = useState(""); const [notice, setNotice] = useState("");
  const refreshServices = useCallback(async () => { try { const response = await api<{ services: Service[] }>("/api/staff/services"); setServices(response.services); setSelected((current) => response.services.find((entry) => entry.queue?.id === current && entry.queue?.status === "OPEN")?.queue?.id ?? response.services.find((entry) => entry.queue?.status === "OPEN")?.queue?.id ?? ""); } catch (e) { setError(e instanceof Error ? e.message : "Unable to load staff services."); } }, []);
  const refreshQueue = useCallback(async () => { if (!selected) return; try { const response = await api<{ queue: { id: string; status: string; service: Service; tokens: Token[] } }>(`/api/staff/queues/${selected}`); setQueue(response.queue); } catch (e) { setError(e instanceof Error ? e.message : "Unable to load this queue."); } }, [selected]);
  const refreshSessionState = useCallback(() => { void refreshServices(); void refreshQueue(); }, [refreshQueue, refreshServices]);
  useEffect(() => { void refreshServices(); }, [refreshServices]); useEffect(() => { void refreshQueue(); }, [refreshQueue]); useQueueEvents(selected ? [selected] : [], refreshQueue); useSessionEvents(refreshSessionState);
  const service = services.find((entry) => entry.queue?.id === selected) ?? services[0];
  const refreshQr = useCallback(async () => { if (!service?.queue || service.queue.status !== "OPEN") { setQr(null); return; } try { setQr(await api<CounterQr>(`/api/staff/services/${service.id}/qr`)); } catch (e) { setQr(null); setError(e instanceof Error ? e.message : "Could not refresh the counter QR."); } }, [service?.id, service?.queue?.id, service?.queue?.status]);
  useEffect(() => { void refreshQr(); if (!qr?.rotationSeconds) return; const handle = window.setInterval(() => void refreshQr(), qr.rotationSeconds * 1_000); return () => window.clearInterval(handle); }, [refreshQr, qr?.rotationSeconds]);
  async function action(path: string, body?: unknown) { try { setNotice(""); const result = await post<{ token?: Token; message?: string }>(path, body); setNotice(result.message ?? (result.token ? `${result.token.displayToken} is now ${nice(result.token.status).toLowerCase()}.` : "Queue updated.")); await refreshQueue(); } catch (e) { setError(e instanceof Error ? e.message : "That action could not be completed."); } }
  const queueIsOpen = queue?.status === "OPEN"; const current = queueIsOpen ? queue?.tokens.find((token) => ["CALLED", "SERVING"].includes(token.status)) : undefined; const checkedIn = queueIsOpen ? queue?.tokens.filter((token) => token.status === "CHECKED_IN") ?? [] : [];
  if (!selected) return <div className="min-h-screen bg-canvas"><PortalHeader user={user} onLogout={onLogout} role="Counter operator" title="Service desk" description="Call only verified students. Queue changes update live for students."/><main className="shell py-7 sm:py-9">{error && <div className="mb-5"><Notice tone="red">{error}</Notice></div>}<Empty title="No active session" detail="An administrator must open an assigned service queue before counter controls and a QR code become available."/></main></div>;
  return <div className="min-h-screen bg-canvas"><PortalHeader user={user} onLogout={onLogout} role="Counter operator" title="Service desk" description="Call only verified students. Queue changes update live for students."/><main className="shell py-7 sm:py-9">{error && <div className="mb-5"><Notice tone="red">{error}</Notice></div>}{notice && <div className="mb-5"><Notice>{notice}</Notice></div>}{services.length === 0 ? <Empty title="No assigned services" detail="Ask an administrator to assign you to a service before operating a queue."/> : <div className="grid gap-6 xl:grid-cols-[minmax(0,1fr)_330px]"><section><div className="card p-4 sm:p-5"><div className="flex flex-col justify-between gap-3 sm:flex-row sm:items-center"><div><p className="eyebrow">Assigned service</p><select aria-label="Select service queue" className="field mt-1 w-full sm:w-80" value={selected} onChange={(e) => setSelected(e.target.value)}>{services.map((entry) => <option key={entry.id} value={entry.queue?.id}>{entry.name} · {entry.queue?.status ?? "No session"}</option>)}</select></div><button className="btn btn-secondary" onClick={() => void refreshQueue()}><RefreshCw size={16}/>Refresh</button></div></div>{queue && <><div className="mt-5 grid gap-4 md:grid-cols-2"><div className="card p-5"><p className="eyebrow">Counter state</p>{current ? <><p className="mt-2 text-3xl font-semibold tracking-[-.05em]">{current.displayToken}</p><p className="mt-1 text-sm text-muted">{current.user?.name ?? "Student"} · {nice(current.status)}</p><div className="mt-5 flex gap-2">{current.status === "CALLED" && <button className="btn btn-primary" onClick={() => action(`/api/staff/tokens/${current.id}/start`)}>Start service</button>}<button className="btn btn-secondary" onClick={() => { const reason = prompt("Reason for skipping (optional)") ?? undefined; void action(`/api/staff/tokens/${current.id}/skip`, { reason }); }}>Skip</button>{current.status === "SERVING" && <button className="btn btn-primary" onClick={() => action(`/api/staff/tokens/${current.id}/complete`)}>Complete</button>}</div></> : <><p className="mt-2 text-lg font-bold">Ready for next student</p><p className="mt-1 text-sm leading-6 text-muted">{checkedIn.length ? `${checkedIn.length} verified student${checkedIn.length === 1 ? "" : "s"} waiting.` : "Waiting for a student to check in."}</p><button className="btn btn-primary mt-5" disabled={!checkedIn.length} onClick={() => action(`/api/staff/queues/${queue.id}/next`)}>Call next verified token</button></>}</div><div className="card p-5"><p className="eyebrow">Queue policy</p><p className="mt-2 text-lg font-bold">Presence before service</p><p className="mt-1 text-sm leading-6 text-muted">Waiting tokens can be temporarily bypassed until their check-in deadline. The first checked-in token is always called in token order.</p><div className="mt-4 flex items-center gap-2 text-sm font-semibold text-teal"><ClipboardCheck size={17}/>Audit history is recorded</div></div></div><QueueTable tokens={queue.tokens} active={current?.id} onSkip={(token) => { const reason = prompt("Reason for skipping (optional)") ?? undefined; void action(`/api/staff/tokens/${token.id}/skip`, { reason }); }}/></>}</section><aside><CounterQr qr={qr} service={service} refresh={refreshQr}/></aside></div>}</main></div>;
}
function QueueTable({ tokens, active, onSkip }: { tokens: Token[]; active?: string; onSkip: (token: Token) => void }) { return <div className="card mt-5 overflow-hidden"><div className="flex items-center justify-between border-b border-line px-5 py-4"><div><p className="eyebrow">Live queue</p><p className="mt-1 text-sm font-bold">{tokens.length} active token{tokens.length === 1 ? "" : "s"}</p></div><Users size={18} className="text-muted"/></div>{tokens.length === 0 ? <p className="px-5 py-8 text-sm text-muted">No active tokens. This queue is clear.</p> : <div className="overflow-x-auto"><table className="min-w-full text-left text-sm"><thead className="bg-canvas text-[11px] font-bold uppercase tracking-[.1em] text-muted"><tr><th className="px-5 py-3">Token</th><th className="px-3 py-3">Student</th><th className="px-3 py-3">Check-in</th><th className="px-3 py-3">Deadline</th><th className="px-5 py-3 text-right">Action</th></tr></thead><tbody className="divide-y divide-line">{tokens.map((token) => <tr key={token.id} className={token.id === active ? "bg-teal/[.035]" : ""}><td className="whitespace-nowrap px-5 py-3.5 font-bold">{token.displayToken}</td><td className="px-3 py-3.5 text-muted">{token.user?.name ?? "Private"}</td><td className="px-3 py-3.5"><Status value={token.status}/></td><td className="whitespace-nowrap px-3 py-3.5 text-xs text-muted">{token.status === "CHECKIN_REQUIRED" ? time(token.checkinDeadlineAt) : "—"}</td><td className="px-5 py-3.5 text-right">{["CALLED", "SERVING"].includes(token.status) && <button className="text-xs font-bold text-red hover:underline" onClick={() => onSkip(token)}>Skip</button>}</td></tr>)}</tbody></table></div>}</div>; }
function CounterQr({ qr, service, refresh }: { qr: CounterQr | null; service?: Service; refresh: () => Promise<void> }) {
  const [copyState, setCopyState] = useState<"idle" | "copied" | "unavailable">("idle");
  async function copyProof() {
    if (!qr) return;
    const copied = await copyTextFromUserGesture(qr.proof);
    setCopyState(copied ? "copied" : "unavailable");
    if (copied) window.setTimeout(() => setCopyState("idle"), 1_600);
  }
  return <div className="card sticky top-5 p-5"><div className="flex items-start justify-between"><div><p className="eyebrow">Counter check-in</p><p className="mt-1 text-sm font-bold">{service?.name ?? "Select a service"}</p></div><button onClick={() => void refresh()} className="rounded-md p-1.5 text-muted hover:bg-canvas" aria-label="Refresh QR"><RefreshCw size={17}/></button></div>{qr ? <><a href={qr.url} className="mx-auto mt-5 grid w-fit place-items-center rounded-lg border border-line bg-white p-3" title="Open authenticated check-in"><QRCodeSVG value={qr.url} size={220} bgColor="#ffffff" fgColor="#17202B" includeMargin={false}/></a><p className="mt-4 text-center text-xs leading-5 text-muted">Students scan this with their camera. A fresh code appears every {qr.rotationSeconds}s; this code remains valid for <span className="font-bold text-ink"><Countdown until={qr.expiresAt} serverTime={qr.serverTime} expiredLabel="expired"/></span>.</p>{qr.allowDemoProof && <><button className="btn btn-secondary mt-4 w-full text-xs" onClick={() => void copyProof()}>{copyState === "copied" ? <><Check size={15}/>Proof copied</> : copyState === "unavailable" ? "Copy unavailable" : "Copy demo proof"}</button>{copyState === "unavailable" ? <div className="mt-3"><p className="text-center text-[11px] leading-4 text-amber">Clipboard access is unavailable in this browser. Select and copy this demo-only proof manually.</p><textarea readOnly aria-label="Selectable demo QR proof" value={qr.proof} onFocus={(event) => event.currentTarget.select()} onClick={(event) => event.currentTarget.select()} className="field mt-2 h-18 resize-none text-[10px] leading-4"/></div> : <p className="mt-2 text-center text-[11px] leading-4 text-muted">Demo only: paste the proof into the authenticated student check-in page. Native camera scanning remains the normal workflow.</p>}</>}</> : <div className="mt-5"><Skeleton/></div>}</div>;
}

function AdminPortal({ user, onLogout }: { user: User; onLogout: () => Promise<void> }) {
  const [analytics, setAnalytics] = useState<any>(null); const [services, setServices] = useState<any[]>([]); const [locations, setLocations] = useState<any[]>([]); const [staff, setStaff] = useState<any[]>([]); const [history, setHistory] = useState<any[]>([]); const [notice, setNotice] = useState(""); const [error, setError] = useState(""); const [adding, setAdding] = useState(false);
  const refresh = useCallback(async () => { try { const [a, b, c, d, e] = await Promise.all([api("/api/admin/analytics"), api<{ services: any[] }>("/api/admin/services"), api<{ locations: any[] }>("/api/admin/locations"), api<{ staff: any[] }>("/api/admin/staff"), api<{ history: any[] }>("/api/admin/history")]); setAnalytics(a); setServices(b.services); setLocations(c.locations); setStaff(d.staff); setHistory(e.history); setError(""); } catch (err) { setError(err instanceof Error ? err.message : "Unable to load administration data."); } }, []);
  useEffect(() => { void refresh(); }, [refresh]);
  async function perform(label: string, work: () => Promise<unknown>) { try { await work(); setNotice(label); await refresh(); } catch (e) { setError(e instanceof Error ? e.message : "That change could not be saved."); } }
  async function addService(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const data = new FormData(event.currentTarget); await perform("Service created and today’s queue opened.", () => post("/api/admin/services", { locationId: data.get("locationId"), name: data.get("name"), code: String(data.get("code") ?? "").toUpperCase(), description: data.get("description"), averageMinutes: Number(data.get("averageMinutes")), active: true })); setAdding(false); }
  return <div className="min-h-screen bg-canvas"><PortalHeader user={user} onLogout={onLogout} role="Administration" title="Operations overview" description="Real queue activity, service controls and audit history in one place."/><main className="shell py-7 sm:py-9">{error && <div className="mb-5"><Notice tone="red">{error}</Notice></div>}{notice && <div className="mb-5"><Notice>{notice}</Notice></div>}{analytics ? <><section className="grid gap-3 sm:grid-cols-2 lg:grid-cols-5"><Stat label="Open queues" value={analytics.summary.activeQueues}/><Stat label="Waiting" value={analytics.summary.waiting}/><Stat label="Checked in" value={analytics.summary.checkedIn}/><Stat label="Completed" value={analytics.summary.completed}/><Stat label="No shows" value={analytics.summary.noShow}/></section><section className="mt-7 grid gap-6 xl:grid-cols-[1.45fr_.8fr]"><div className="space-y-6"><div className="card overflow-hidden"><div className="flex items-center justify-between border-b border-line px-5 py-4"><div><p className="eyebrow">Service sessions</p><p className="mt-1 text-sm font-bold">Today’s operating queues</p></div><button className="btn btn-primary min-h-9 px-3 text-xs" onClick={() => setAdding(!adding)}><Plus size={15}/>New service</button></div>{adding && <form onSubmit={addService} className="grid gap-3 border-b border-line bg-canvas p-5 sm:grid-cols-2"><label className="text-xs font-bold">Name<input required name="name" className="field" placeholder="Career Services"/></label><label className="text-xs font-bold">Code<input required name="code" maxLength={5} pattern="[A-Za-z]{2,5}" className="field" placeholder="CAR"/></label><label className="text-xs font-bold">Location<select required name="locationId" className="field"><option value="">Select location</option>{locations.filter((l) => l.active).map((l) => <option value={l.id} key={l.id}>{l.name}</option>)}</select></label><label className="text-xs font-bold">Average minutes<input required name="averageMinutes" type="number" min="1" max="120" defaultValue="8" className="field"/></label><label className="text-xs font-bold sm:col-span-2">Description<input required name="description" className="field" placeholder="What students can get help with"/></label><div className="sm:col-span-2 flex gap-2"><button className="btn btn-primary" type="submit">Create service</button><button className="btn btn-secondary" type="button" onClick={() => setAdding(false)}>Cancel</button></div></form>}<div className="divide-y divide-line">{services.map((service) => <div className="flex flex-col gap-3 p-5 sm:flex-row sm:items-center sm:justify-between" key={service.id}><div><div className="flex items-center gap-2"><p className="text-sm font-bold">{service.name}</p><Status value={service.queues?.[0]?.status ?? "CLOSED"}/></div><p className="mt-1 text-xs text-muted">{service.code} · {service.location.name} · {service.averageMinutes} min average</p></div><div className="flex flex-wrap gap-2"><button className="btn btn-secondary min-h-8 px-3 text-xs" onClick={() => perform(`Policy updated for ${service.name}.`, () => patch(`/api/admin/services/${service.id}/policy`, { checkinLeadMinutes: service.checkinLeadMinutes, checkinLeadTokens: service.checkinLeadTokens, checkinGraceMinutes: service.checkinGraceMinutes }))}>Policy</button><button className="btn btn-secondary min-h-8 px-3 text-xs" onClick={() => perform(`${service.name} ${service.active ? "disabled" : "enabled"}.`, () => patch(`/api/admin/services/${service.id}`, { active: !service.active }))}>{service.active ? "Disable" : "Enable"}</button>{service.queues?.[0] && <button className="btn btn-secondary min-h-8 px-3 text-xs" onClick={() => perform(`Queue ${service.queues[0].status === "OPEN" ? "closed" : "opened"}.`, () => post(`/api/admin/queues/${service.queues[0].id}/${service.queues[0].status === "OPEN" ? "close" : "open"}`))}>{service.queues[0].status === "OPEN" ? "Close queue" : "Open queue"}</button>}</div></div>)}</div></div><AdminAssignments staff={staff} services={services} perform={perform}/></div><aside className="space-y-6"><div className="card p-5"><p className="eyebrow">Service quality</p><p className="mt-2 text-3xl font-semibold tracking-[-.05em]">{analytics.summary.averageJourneyMinutes === null ? "—" : `${analytics.summary.averageJourneyMinutes} min`}</p><p className="mt-1 text-sm leading-6 text-muted">Average join-to-completion time. {analytics.summary.averageJourneyMinutes === null ? "Not enough completed records yet." : "Based on stored completed tokens."}</p></div><div className="card p-5"><p className="eyebrow">Demo control</p><p className="mt-2 text-sm font-bold">Automatic no-show scenario</p><p className="mt-1 text-sm leading-6 text-muted">Opens the oldest waiting demo token’s short presence window. The scheduler performs the no-show transition.</p><button className="btn btn-secondary mt-4 w-full text-xs" onClick={() => perform("Demo no-show window opened. Wait for the persisted scheduler transition.", () => post("/api/admin/demo/open-no-show"))}>Open demo no-show window</button></div><div className="card p-5"><p className="eyebrow">Daily service summary</p><div className="mt-3 space-y-3">{analytics.services.map((service: any) => <div key={service.id} className="flex items-center justify-between text-sm"><span className="font-semibold">{service.code}</span><span className="text-muted">{service.joined} joined · {service.completed} complete · {service.noShow} no-show</span></div>)}</div></div></aside></section><section className="card mt-7 overflow-hidden"><div className="border-b border-line px-5 py-4"><p className="eyebrow">Audit trail</p><p className="mt-1 text-sm font-bold">Latest queue decisions</p></div><div className="overflow-x-auto"><table className="min-w-full text-left text-sm"><thead className="bg-canvas text-[11px] font-bold uppercase tracking-[.1em] text-muted"><tr><th className="px-5 py-3">When</th><th className="px-3 py-3">Token</th><th className="px-3 py-3">Action</th><th className="px-5 py-3">Actor</th></tr></thead><tbody className="divide-y divide-line">{history.slice(0, 12).map((entry) => <tr key={entry.id}><td className="whitespace-nowrap px-5 py-3 text-xs text-muted">{date(entry.createdAt)}</td><td className="px-3 py-3 font-bold">{entry.token?.displayToken ?? "—"} <span className="font-normal text-muted">{entry.token?.queue?.service?.code}</span></td><td className="px-3 py-3">{nice(entry.action.toUpperCase())}</td><td className="px-5 py-3 text-muted">{entry.actorType.toLowerCase()}</td></tr>)}</tbody></table></div></section></> : <Skeleton/>}</main></div>;
}
function Stat({ label, value }: { label: string; value: number }) { return <div className="card p-4"><p className="eyebrow">{label}</p><p className="mt-2 text-2xl font-semibold tracking-[-.05em]">{value}</p></div>; }

function AdminPortalV2({ user, onLogout }: { user: User; onLogout: () => Promise<void> }) {
  const [analytics, setAnalytics] = useState<any>(null);
  const [services, setServices] = useState<any[]>([]);
  const [locations, setLocations] = useState<any[]>([]);
  const [staff, setStaff] = useState<any[]>([]);
  const [history, setHistory] = useState<any[]>([]);
  const [notice, setNotice] = useState("");
  const [error, setError] = useState("");
  const [adding, setAdding] = useState(false);
  const refresh = useCallback(async () => {
    try {
      const [a, b, c, d, e] = await Promise.all([
        api<any>("/api/admin/analytics"),
        api<{ services: any[] }>("/api/admin/services"),
        api<{ locations: any[] }>("/api/admin/locations"),
        api<{ staff: any[] }>("/api/admin/staff"),
        api<{ history: any[] }>("/api/admin/history")
      ]);
      setAnalytics(a); setServices(b.services); setLocations(c.locations); setStaff(d.staff); setHistory(e.history); setError("");
    } catch (cause) { setError(cause instanceof Error ? cause.message : "Unable to load administration data."); }
  }, []);
  useEffect(() => { void refresh(); }, [refresh]);
  useSessionEvents(refresh);
  async function perform(fallback: string, work: () => Promise<any>) {
    try { const result = await work(); setNotice(result?.message ?? fallback); await refresh(); }
    catch (cause) { setError(cause instanceof Error ? cause.message : "That change could not be saved."); }
  }
  async function addService(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const form = new FormData(event.currentTarget);
    await perform("Service created and today’s queue opened.", () => post("/api/admin/services", {
      locationId: form.get("locationId"), name: form.get("name"), code: String(form.get("code") ?? "").toUpperCase(),
      description: form.get("description"), averageMinutes: Number(form.get("averageMinutes")), active: true
    }));
    setAdding(false);
  }
  async function changeSession(service: any) {
    const isOpen = service.queues?.[0]?.status === "OPEN";
    if (isOpen && !window.confirm(`Close ${service.name}? Waiting and checked-in tokens that have not reached the counter will be cancelled, while an in-service token blocks closure.`)) return;
    await perform(`${service.name} queue ${isOpen ? "closed" : "opened"}.`, () => post(`/api/admin/services/${service.id}/queue/${isOpen ? "close" : "open"}`));
  }
  return <div className="min-h-screen bg-canvas"><PortalHeader user={user} onLogout={onLogout} role="Administration" title="Operations overview" description="Current operating queues, service controls and audit history in one place."/><main className="shell py-7 sm:py-9">
    {error && <div className="mb-5"><Notice tone="red">{error}</Notice></div>}{notice && <div className="mb-5"><Notice>{notice}</Notice></div>}
    {!analytics ? <Skeleton/> : <>
      <section className="grid gap-3 sm:grid-cols-2 lg:grid-cols-5"><Stat label="Open queues" value={analytics.summary.activeQueues}/><Stat label="Waiting" value={analytics.summary.waiting}/><Stat label="Checked in" value={analytics.summary.checkedIn}/><Stat label="Completed" value={analytics.summary.completed}/><Stat label="No shows" value={analytics.summary.noShow}/></section>
      <section className="mt-7 grid gap-6 xl:grid-cols-[1.45fr_.8fr]"><div className="space-y-6"><div className="card overflow-hidden"><div className="flex items-center justify-between border-b border-line px-5 py-4"><div><p className="eyebrow">Service sessions</p><p className="mt-1 text-sm font-bold">Operating day {analytics.operatingDate} · {analytics.timeZone}</p></div><button className="btn btn-primary min-h-9 px-3 text-xs" onClick={() => setAdding((value) => !value)}><Plus size={15}/>New service</button></div>
        {adding && <form onSubmit={addService} className="grid gap-3 border-b border-line bg-canvas p-5 sm:grid-cols-2"><label className="text-xs font-bold">Name<input required name="name" className="field" placeholder="Career Services"/></label><label className="text-xs font-bold">Code<input required name="code" maxLength={5} pattern="[A-Za-z]{2,5}" className="field" placeholder="CAR"/></label><label className="text-xs font-bold">Location<select required name="locationId" className="field"><option value="">Select location</option>{locations.filter((location) => location.active).map((location) => <option value={location.id} key={location.id}>{location.name}</option>)}</select></label><label className="text-xs font-bold">Average minutes<input required name="averageMinutes" type="number" min="1" max="120" defaultValue="8" className="field"/></label><label className="text-xs font-bold sm:col-span-2">Description<input required name="description" className="field" placeholder="What students can get help with"/></label><div className="flex gap-2 sm:col-span-2"><button className="btn btn-primary" type="submit">Create service</button><button className="btn btn-secondary" type="button" onClick={() => setAdding(false)}>Cancel</button></div></form>}
        <div className="divide-y divide-line">{services.map((service) => { const isOpen = service.queues?.[0]?.status === "OPEN"; return <div className="flex flex-col gap-3 p-5 sm:flex-row sm:items-center sm:justify-between" key={service.id}><div><div className="flex items-center gap-2"><p className="text-sm font-bold">{service.name}</p><Status value={isOpen ? "OPEN" : "CLOSED"}/></div><p className="mt-1 text-xs text-muted">{service.code} · {service.location.name} · {service.averageMinutes} min average</p></div><div className="flex flex-wrap gap-2"><button className="btn btn-secondary min-h-8 px-3 text-xs" onClick={() => void perform(`Policy updated for ${service.name}.`, () => patch(`/api/admin/services/${service.id}/policy`, { checkinLeadMinutes: service.checkinLeadMinutes, checkinLeadTokens: service.checkinLeadTokens, checkinGraceMinutes: service.checkinGraceMinutes }))}>Policy</button><button className="btn btn-secondary min-h-8 px-3 text-xs" onClick={() => void perform(`${service.name} ${service.active ? "disabled" : "enabled"}.`, () => patch(`/api/admin/services/${service.id}`, { active: !service.active }))}>{service.active ? "Disable" : "Enable"}</button><button disabled={!service.active} className="btn btn-secondary min-h-8 px-3 text-xs" onClick={() => void changeSession(service)}>{isOpen ? "Close Queue" : "Open Queue"}</button></div></div>; })}</div>
      </div><AdminAssignments staff={staff} services={services} perform={perform}/></div><aside className="space-y-6"><div className="card p-5"><p className="eyebrow">Service quality · today</p><p className="mt-2 text-3xl font-semibold tracking-[-.05em]">{analytics.summary.averageServiceMinutes === null ? "—" : `${analytics.summary.averageServiceMinutes} min`}</p><p className="mt-1 text-sm leading-6 text-muted">Average start-to-completion service duration. {analytics.summary.averageServiceMinutes === null ? "No completed services in this operating day." : "Based on persisted completed tokens."}</p></div><div className="card p-5"><p className="eyebrow">Demo control</p><p className="mt-2 text-sm font-bold">Automatic no-show scenario</p><p className="mt-1 text-sm leading-6 text-muted">Opens the oldest waiting demo token’s short presence window. The scheduler performs the no-show transition.</p><button className="btn btn-secondary mt-4 w-full text-xs" onClick={() => void perform("Demo no-show window opened. Wait for the persisted scheduler transition.", () => post("/api/admin/demo/open-no-show"))}>Open demo no-show window</button></div><div className="card p-5"><p className="eyebrow">Daily service summary</p><div className="mt-3 space-y-3">{analytics.services.map((service: any) => <div key={service.id} className="flex items-center justify-between text-sm"><span className="font-semibold">{service.code}</span><span className="text-muted">{service.joined} joined · {service.completed} complete · {service.noShow} no-show</span></div>)}</div></div></aside></section>
      <section className="card mt-7 overflow-hidden"><div className="border-b border-line px-5 py-4"><p className="eyebrow">Audit trail</p><p className="mt-1 text-sm font-bold">Latest token and session decisions</p></div><div className="overflow-x-auto"><table className="min-w-full text-left text-sm"><thead className="bg-canvas text-[11px] font-bold uppercase tracking-[.1em] text-muted"><tr><th className="px-5 py-3">When</th><th className="px-3 py-3">Token / service</th><th className="px-3 py-3">Action</th><th className="px-5 py-3">Actor</th></tr></thead><tbody className="divide-y divide-line">{history.slice(0, 12).map((entry) => <tr key={entry.id}><td className="whitespace-nowrap px-5 py-3 text-xs text-muted">{date(entry.createdAt)}</td><td className="px-3 py-3 font-bold">{entry.token?.displayToken ?? entry.service?.code ?? "—"} <span className="font-normal text-muted">{entry.token?.queue?.service?.code ?? entry.service?.name}</span></td><td className="px-3 py-3">{nice(entry.action.toUpperCase())}</td><td className="px-5 py-3 text-muted">{entry.actorType.toLowerCase()}</td></tr>)}</tbody></table></div></section>
    </>}
  </main></div>;
}
function AdminAssignments({ staff, services, perform }: { staff: any[]; services: any[]; perform: (label: string, work: () => Promise<unknown>) => Promise<void> }) { const [staffId, setStaffId] = useState(""); const [serviceId, setServiceId] = useState(""); return <div className="card p-5"><p className="eyebrow">Staff assignments</p><p className="mt-1 text-sm font-bold">Counter access</p><div className="mt-4 flex flex-col gap-2 sm:flex-row"><select className="field mt-0" value={staffId} onChange={(e) => setStaffId(e.target.value)}><option value="">Choose staff member</option>{staff.map((member) => <option value={member.id} key={member.id}>{member.user.name}</option>)}</select><select className="field mt-0" value={serviceId} onChange={(e) => setServiceId(e.target.value)}><option value="">Choose service</option>{services.map((service) => <option value={service.id} key={service.id}>{service.name}</option>)}</select><button disabled={!staffId || !serviceId} className="btn btn-primary shrink-0" onClick={() => void perform("Staff assignment saved.", () => post("/api/admin/assignments", { staffId, serviceId }))}>Assign</button></div><div className="mt-4 divide-y divide-line">{staff.map((member) => <div className="py-3" key={member.id}><p className="text-sm font-bold">{member.user.name}</p><div className="mt-2 flex flex-wrap gap-2">{member.assignments.length ? member.assignments.map((assignment: any) => <span className="inline-flex items-center gap-1 rounded-md bg-canvas px-2 py-1 text-xs" key={assignment.id}>{assignment.service.name}<button aria-label={`Remove ${assignment.service.name}`} className="text-red" onClick={() => void perform("Staff assignment removed.", () => remove(`/api/admin/assignments/${assignment.id}`))}><X size={13}/></button></span>) : <span className="text-xs text-muted">No assigned services</span>}</div></div>)}</div></div>; }

export { AdminPortal };
